package com.mobileapi.audit

import java.io._
import java.nio.file._
import java.nio.file.attribute._
import java.security.SecureRandom
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

trait AuditSerializer {
  def serialize(entry: AuditEntry): Array[Byte]
  def deserialize(data: Array[Byte]): AuditEntry
}

case class AuditEntry(
  userId: String,
  action: String,
  resource: String,
  timestamp: Long,
  metadata: Map[String, String]
)

class SecureAuditSerializer extends AuditSerializer {
  override def serialize(entry: AuditEntry): Array[Byte] = {
    val sb = new StringBuilder
    sb.append(s"${entry.userId}|${entry.action}|${entry.resource}|${entry.timestamp}")
    entry.metadata.foreach { case (k, v) => sb.append(s"|$k=$v") }
    sb.toString.getBytes("UTF-8")
  }

  override def deserialize(data: Array[Byte]): AuditEntry = {
    val parts = new String(data, "UTF-8").split("\\|")
    AuditEntry(parts(0), parts(1), parts(2), parts(3).toLong, Map.empty)
  }
}

object TempFileStrategy {
  sealed trait Mode
  case object Atomic extends Mode
  case object Streaming extends Mode
}

class AuditBufferManager(
  baseDir: Path,
  serializer: AuditSerializer,
  mode: TempFileStrategy.Mode = TempFileStrategy.Atomic
) {
  private val random = new SecureRandom()
  private val activeBuffers = new TrieMap[String, Path]()
  private val SESSION_PREFIX = "audit_buf_"

  private def generateToken(): String = {
    val bytes = new Array[Byte](16)
    random.nextBytes(bytes)
    bytes.map("%02x".format(_)).mkString
  }

  def initializeBuffer(sessionId: String): Path = {
    val token = generateToken()
    val tempPath = createSecureTempFile(sessionId, token)
    activeBuffers.put(sessionId, tempPath)
    tempPath
  }

  private def createSecureTempFile(sessionId: String, token: String): Path = {
    val fileName = s"${SESSION_PREFIX}${sessionId}_${token}"
    mode match {
      case TempFileStrategy.Atomic =>
        createAtomicTempFile(fileName)
      case TempFileStrategy.Streaming =>
        createStreamingTempFile(fileName)
    }
  }

  private def createAtomicTempFile(fileName: String): Path = {
    val dirPermissions = PosixFilePermissions.asFileAttribute(
      PosixFilePermissions.fromString("rwx------")
    )
    val sessionDir = Files.createTempDirectory(baseDir, "session_")
    val tempFile = sessionDir.resolve(fileName)
    val filePermissions = PosixFilePermissions.asFileAttribute(
      PosixFilePermissions.fromString("rw-------")
    )
    Files.createFile(tempFile, filePermissions)
    tempFile
  }

  private def createStreamingTempFile(fileName: String): Path = {
    val tempFile = baseDir.resolve(fileName)
    if (!Files.exists(tempFile)) {
      Files.createFile(tempFile)
    }
    tempFile
  }

  def appendAuditEntry(sessionId: String, entry: AuditEntry): Try[Unit] = Try {
    activeBuffers.get(sessionId) match {
      case Some(path) =>
        val data = serializer.serialize(entry)
        val os = new FileOutputStream(path.toFile, true)
        try {
          os.write(data)
          os.write('\n')
        } finally {
          os.close()
        }
      case None =>
        throw new IllegalStateException(s"No active buffer for session: $sessionId")
    }
  }

  def flushBuffer(sessionId: String, targetPath: Path): Try[Long] = Try {
    activeBuffers.remove(sessionId) match {
      case Some(bufferPath) =>
        val size = Files.size(bufferPath)
        Files.move(bufferPath, targetPath, StandardCopyOption.ATOMIC_MOVE)
        size
      case None =>
        throw new IllegalStateException(s"No buffer to flush for session: $sessionId")
    }
  }

  def cleanupExpiredBuffers(maxAgeSeconds: Long): Int = {
    val cutoff = Instant.now().minusSeconds(maxAgeSeconds)
    var cleaned = 0
    activeBuffers.foreach { case (sid, path) =>
      Try {
        val attrs = Files.readAttributes(path, classOf[BasicFileAttributes])
        if (attrs.creationTime().toInstant.isBefore(cutoff)) {
          Files.deleteIfExists(path)
          activeBuffers.remove(sid)
          cleaned += 1
        }
      }
    }
    cleaned
  }
}

class MobileAuditService(config: AuditServiceConfig) {
  private val serializer = new SecureAuditSerializer()
  private val bufferManager = new AuditBufferManager(
    config.tempDirectory,
    serializer,
    config.bufferMode
  )

  def startSession(userId: String): String = {
    val sessionId = s"${userId}_${System.currentTimeMillis()}"
    bufferManager.initializeBuffer(sessionId)
    sessionId
  }

  def logAction(sessionId: String, action: String, resource: String,
                metadata: Map[String, String] = Map.empty): Try[Unit] = {
    val entry = AuditEntry(
      userId = sessionId.split("_").head,
      action = action,
      resource = resource,
      timestamp = System.currentTimeMillis(),
      metadata = metadata
    )
    bufferManager.appendAuditEntry(sessionId, entry)
  }

  def finalizeSession(sessionId: String): Try[Long] = {
    val archivePath = config.archiveDirectory.resolve(s"audit_${sessionId}.log")
    bufferManager.flushBuffer(sessionId, archivePath)
  }
}

case class AuditServiceConfig(
  tempDirectory: Path,
  archiveDirectory: Path,
  bufferMode: TempFileStrategy.Mode
)
